import {PARTS,THEMES,DEFAULT,WEATHER,partsFor,statsFor,randomBuild,createFlight,stepFlight} from './game.js';
import {createScene} from './scene.js';
const $=s=>document.querySelector(s);
const icons={nose:'<path d="M5 25V16Q5 7 13 2Q21 7 21 16V25Z M5 20h16"/>',hull:'<rect x="6" y="3" width="14" height="24" rx="3"/><path d="M6 8h14M6 22h14M10 12h6"/>',fins:'<path d="M11 3h4v22h-4zM11 11L3 24h8M15 11l8 13h-8"/>',engine:'<path d="M8 3h10l-2 8 5 12H5l5-12zM9 27h8M9 7h8"/>',fuel:'<rect x="6" y="3" width="14" height="24" rx="6"/><path d="M6 10h14M6 20h14M13 12l-3 5h5l-2 3"/>',recovery:'<path d="M3 13a10 10 0 0120 0H3zM3 13l10 14 10-14M8 13l5 14 5-14M13 3v10"/>'};
const icon=k=>`<svg viewBox="0 0 26 30" aria-hidden="true">${icons[k]}</svg>`;
const labels={nose:'NOSE CONE',hull:'BODY',fins:'FINS',engine:'ENGINE',fuel:'PROPELLANT',recovery:'RECOVERY'};
let build={...DEFAULT},weatherIndex=0,selected=null,mode='build',flight=null,throttle=1,runId=0,launchCount=0,scene,toastTimer;
const app=$('#app');
app.innerHTML=`<div class="workspace-heading"><div><div class="eyebrow">MISSION 001 / THE EDGE OF SPACE</div><h1>Your rocket. Your rules.</h1></div><div class="steps"><span class="active" id="step-build"><b>01</b> BUILD</span><i class="step-line"></i><span id="step-launch"><b>02</b> LAUNCH</span><i class="step-line"></i><span id="step-report"><b>03</b> DISCOVER</span></div></div>
<div class="workbench"><aside class="build-column"><section class="panel"><div class="panel-title">ASSEMBLY BAY <span class="count">6 / 6 PARTS</span></div><div class="theme-picker" role="group" aria-label="Design theme">${Object.entries(THEMES).map(([k,t])=>`<button class="theme" data-theme="${k}" aria-pressed="false">${t.name}</button>`).join('')}</div><div class="parts">${Object.keys(PARTS).map(k=>`<button class="part" data-part="${k}" aria-haspopup="dialog" aria-expanded="false"><span class="part-icon">${icon(k)}</span><span class="part-text"><small>${labels[k]}</small><strong></strong></span><span class="part-chevron">›</span></button>`).join('')}</div><div class="parts-footer">CLICK A PART TO SWAP IT OUT</div></section><section class="panel small-panel"><div><div class="label-row"><label>FLIGHT COLORS</label><span class="muted">01 / 05</span></div><div class="swatches" role="group" aria-label="Rocket accent color">${[['#ff7048','Solar orange'],['#c6deaa','Lunar green'],['#a5d4e7','Glacier blue'],['#b68aff','Ultraviolet'],['#e8c676','Brass gold']].map(([c,n])=>`<button class="swatch" style="--color:${c}" data-color="${c}" aria-label="${n}" aria-pressed="false"></button>`).join('')}</div></div><div class="fuel-control" style="margin-top:18px"><div class="label-row"><label for="fuel-load">FUEL LOAD</label><span id="load-label">100%</span></div><input class="fuel-slider" id="fuel-load" type="range" min="35" max="100" value="100" step="5"></div></section></aside>
<section class="scene-column" aria-label="Rocket preview"><div class="canvas-panel" id="viewport"><div class="viewport-top"><span class="viewport-tag" id="viewport-status">LIVE ASSEMBLY</span><span class="outline-tag" id="model-tag">3D WORKSPACE</span></div><div class="viewport-number">SF—01</div><div class="viewport-caption">EXPERIMENTAL FLIGHT DIVISION</div><div class="scene-controls"><button class="icon-button" id="zoom-in" aria-label="Zoom in">+</button><button class="icon-button" id="zoom-out" aria-label="Zoom out">−</button><button class="icon-button" id="reset-view" aria-label="Reset camera view">⌖</button><button class="icon-button" id="rotate" aria-label="Toggle automatic rotation" aria-pressed="true">↻</button></div><div class="viewport-bottom"><div><div class="rocket-id">SF / <span id="theme-label">RETRO FUTURE</span></div><input class="name-input" id="rocket-name" aria-label="Rocket name" maxlength="28" value="Pioneer 01" spellcheck="false"></div><span class="orbit-hint">DRAG TO ORBIT<br>SCROLL TO ZOOM</span></div><div id="picker-slot"></div><div id="flight-slot"></div></div><div class="canvas-under"><button class="secondary-button random-button" id="random"><span class="dice">⚄</span> Random design</button><button class="secondary-button reset-button" id="reset">Reset build</button></div></section>
<aside class="mission-column"><section class="panel mission"><div class="micro">YOUR FIRST FRONTIER</div><h2>Touch the edge of space.</h2><p class="mission-description">Cross the Kármán line. Then bring your creation home in one piece.</p><div class="mission-target"><strong class="target-value">100</strong><span>km</span><small>TARGET ALTITUDE</small></div><div class="target-track"><div class="target-progress" id="mission-progress"></div></div><div class="weather-box"><div class="weather-row"><span id="weather-name"></span><button id="weather" aria-label="Change launch weather">↻</button></div><p id="weather-description"></p></div></section><section class="panel"><div class="stats-panel"><div class="micro">FLIGHT READINESS</div><div id="stats"></div></div><div class="readiness" id="readiness"></div><details class="audit-details" id="audit"><summary id="audit-summary">Preflight checks</summary><div id="audit-content"></div></details><div id="control-slot"></div></section><div class="launch-wrap"><button class="launch-button" id="launch">${icon('engine')}<span>Launch rocket</span></button><div class="launch-help">A LITTLE SCIENCE. A LOT OF POSSIBILITIES.</div></div></aside></div><footer class="workspace-footer"><span>✳ <b>MADE FOR THE EXPLORERS.</b></span><span class="tip">Every part changes the flight. Experiment. Fail spectacularly. Try again.</span><button class="help-button" id="how">Flight manual</button></footer>
<dialog class="howto" id="manual"><h2>From the workbench to space.</h2><p>Your mission: reach 100 km and land safely. This is a playful, simplified flight simulation.</p><ol><li><strong>Assemble.</strong> Select a part to compare options. Match engine and propellant, keep thrust-to-weight above 1, and use stable fins.</li><li><strong>Check.</strong> Wind makes unstable designs harder to fly. Fragile parts can overheat. The recovery chute is your ticket home.</li><li><strong>Launch.</strong> Adjust throttle to manage heat. Cutting engines starts an early return. The chute deploys automatically.</li><li><strong>Learn.</strong> Review the flight result, change your build, and try again. Random designs are experiments, not guaranteed winners.</li></ol><p>Flights use accelerated time. Theme and paint are cosmetic; hardware, fuel load, throttle, and weather affect the result. Drag to orbit the rocket, or use the view buttons.</p><button class="secondary-button" id="close-manual">Back to the workshop</button></dialog>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function render(){const s=statsFor(build,WEATHER[weatherIndex]),p=s.p;
 for(const k of Object.keys(PARTS)){$(`[data-part="${k}"] strong`).textContent=p[k].name;$(`[data-part="${k}"]`).classList.toggle('selected',selected===k);$(`[data-part="${k}"]`).setAttribute('aria-expanded',String(selected===k));}
 document.querySelectorAll('[data-theme]').forEach(b=>{const yes=b.dataset.theme===build.theme;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});
 document.querySelectorAll('[data-color]').forEach(b=>{const yes=b.dataset.color===build.paint;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});
 $('#theme-label').textContent=THEMES[build.theme].name.toUpperCase();$('#rocket-name').value=build.name;$('#fuel-load').value=build.load;$('#load-label').textContent=build.load+'%';
 $('#weather-name').textContent='☼ '+WEATHER[weatherIndex].name+' · '+WEATHER[weatherIndex].wind+' km/h';$('#weather-description').textContent=WEATHER[weatherIndex].description;
 const stats=[['Total mass',(s.mass/1000).toFixed(2)+' t',s.mass/24,false],['Thrust / weight',s.twr.toFixed(2)+' TWR',Math.min(s.twr/5*100,100),s.twr<1.15],['Stability',Math.round(s.stability)+'%',s.stability,s.stability<65],['Heat tolerance',s.heat.toLocaleString()+' °C',s.heat/18,s.heat<900]];
 $('#stats').innerHTML=stats.map(([label,value,width,bad])=>`<div class="stat"><div class="stat-title"><span>${label}</span><strong>${value}</strong></div><div class="meter"><span class="${bad?'bad':label==='Stability'?'good':''}" style="width:${Math.max(0,Math.min(width,100))}%"></span></div></div>`).join('');
 const danger=s.issues.some(i=>i.level==='danger');$('#readiness').className='readiness'+(s.issues.length?' warning':'');$('#readiness').textContent=s.issues.length?'△ '+s.issues.length+' preflight '+(s.issues.length===1?'warning':'warnings'):'✓ All systems go';
 $('#audit-summary').textContent=s.issues.length?'Review launch risks':'Preflight checks passed';$('#audit-content').innerHTML=s.issues.length?s.issues.map(i=>`<p><strong>${i.title}</strong><br>${i.text}</p>`).join(''):'<p>Propellant matched. Thrust, stability, and heat protection look good. Recovery chute fitted.</p>';
 $('#launch span').textContent=mode==='build'?(danger?'Launch anyway':'Launch rocket'):mode==='result'?'Back to workshop':'Flight in progress';
 $('#launch').disabled=mode==='countdown'||mode==='flight'||!scene;
 document.querySelectorAll('[data-part],[data-theme],[data-color],#random,#reset,#weather,#fuel-load,#rocket-name').forEach(el=>el.disabled=mode!=='build');
 $('#step-build').classList.toggle('active',mode==='build');$('#step-launch').classList.toggle('active',mode==='flight'||mode==='countdown');$('#step-report').classList.toggle('active',mode==='result');
}
function rebuild(){scene?.clearFlight();scene?.build(build);render();}
function closePicker(){const key=selected;selected=null;$('#picker-slot').replaceChildren();render();if(key)$(`[data-part="${key}"]`).focus({preventScroll:true});}
function choosePart(k,id){if(mode!=='build')throw Error('Finish this flight before changing parts.');if(typeof k!=='string'||!Object.hasOwn(PARTS,k)||typeof id!=='string'||!PARTS[k].some(p=>p.id===id))throw Error('Unknown rocket part.');build[k]=id;selected=null;$('#picker-slot').replaceChildren();rebuild();}
function openPicker(k){if(mode!=='build')return;if(selected===k){closePicker();return;}selected=k;render();$('#picker-slot').innerHTML=`<section class="part-picker" role="dialog" aria-label="Choose ${labels[k].toLowerCase()}"><div class="picker-heading">${labels[k]}<button class="close-picker" aria-label="Close part picker">×</button></div>${PARTS[k].map(p=>`<button class="part-option" data-choice="${p.id}" aria-pressed="${build[k]===p.id}"><strong class="option-name">${p.name}</strong><span class="option-tag">${p.tag}</span><p>${p.note}</p><span class="option-mass">${p.mass} KG DRY MASS</span></button>`).join('')}</section>`;$('.close-picker').onclick=closePicker;document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{choosePart(k,el.dataset.choice);$(`[data-part="${k}"]`).focus({preventScroll:true});});$('.close-picker').focus({preventScroll:true});if(matchMedia('(max-width:600px)').matches)$('#viewport').scrollIntoView({block:'start',behavior:'smooth'});}
try{scene=createScene($('#viewport'));scene.build(build);}catch(error){const div=document.createElement('div');div.className='webgl-error';const h=document.createElement('strong');h.textContent='The 3D workshop needs WebGL';const p=document.createElement('p');p.textContent='Enable hardware acceleration or try a current browser. You can still explore parts and preflight checks.';div.append(h,p);$('#viewport').append(div);console.error('WebGL initialization failed',error);}
for(const k of Object.keys(PARTS))$(`[data-part="${k}"]`).onclick=()=>openPicker(k);
for(const b of document.querySelectorAll('[data-theme]'))b.onclick=()=>{build.theme=b.dataset.theme;build.paint=THEMES[build.theme].color;rebuild();};
for(const b of document.querySelectorAll('[data-color]'))b.onclick=()=>{build.paint=b.dataset.color;rebuild();};
$('#fuel-load').oninput=e=>{build.load=Number(e.target.value);render();};$('#rocket-name').oninput=e=>{build.name=e.target.value.slice(0,28);};$('#rocket-name').onblur=()=>{build.name=build.name.trim()||DEFAULT.name;render();};
$('#random').onclick=()=>{closePicker();build=randomBuild();rebuild();toast('New experiment assembled. Check the launch risks.');};$('#reset').onclick=()=>{closePicker();build={...DEFAULT};weatherIndex=0;rebuild();toast('Pioneer 01 restored.');};$('#weather').onclick=()=>{weatherIndex=(weatherIndex+1)%WEATHER.length;render();};
$('#zoom-in').onclick=()=>scene?.zoom(.88);$('#zoom-out').onclick=()=>scene?.zoom(1.12);$('#reset-view').onclick=()=>scene?.resetView();$('#rotate').onclick=()=>$('#rotate').setAttribute('aria-pressed',String(scene?.rotate()));
$('#how').onclick=()=>$('#manual').showModal();$('#close-manual').onclick=()=>$('#manual').close();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&selected)closePicker();});
function returnToBuild(){runId++;mode='build';flight=null;throttle=1;$('#flight-slot').replaceChildren();$('#control-slot').replaceChildren();$('#viewport-status').textContent='LIVE ASSEMBLY';$('#model-tag').textContent='3D WORKSPACE';$('.viewport-number').hidden=false;$('.viewport-caption').hidden=false;$('#mission-progress').style.width='0%';rebuild();}
function renderFlight(){const f=flight;if(!f)return;$('#altitude').textContent=(Math.max(0,f.altitude)/1000).toFixed(1);$('#velocity').textContent=Math.round(Math.abs(f.velocity));$('#flight-fuel').textContent=Math.max(0,Math.round(f.fuel/f.stats.fuelMass*100));$('#flight-phase').textContent=({powered:'POWERED ASCENT',coast:'COASTING TO APOGEE',descent:'RETURNING TO EARTH',recovery:'CHUTE DEPLOYED',landed:'TOUCHDOWN',explosion:'SIGNAL LOST'})[f.phase];$('#flight-message').textContent=f.reachedSpace?'Kármán line crossed. Bring it home.':f.aborted?'Engine cut. Recovery sequence active.':`${Math.round(f.temperature)} °C skin temperature · T+${Math.floor(f.time)}s`;$('#mission-progress').style.width=Math.min(100,f.maxAltitude/1000)+'%';}
function finishFlight(){mode='result';render();$('#viewport-status').textContent=flight.status==='success'?'MISSION COMPLETE':'FLIGHT COMPLETE';const r=document.createElement('section');r.className='result'+(flight.status==='success'?' success':'');r.setAttribute('role','dialog');r.setAttribute('aria-label','Flight report');const symbol=document.createElement('div');symbol.className='result-symbol';symbol.textContent=flight.status==='success'?'✳':flight.status==='recovered'?'◎':'△';const h=document.createElement('h2');h.textContent=flight.cause.title;const p=document.createElement('p');p.textContent=flight.cause.text;const stats=document.createElement('div');stats.className='result-stats';stats.innerHTML=`<div><small>PEAK ALTITUDE</small><strong>${(flight.maxAltitude/1000).toFixed(1)} <small style="display:inline">km</small></strong></div><div><small>TOP SPEED</small><strong>${Math.round(flight.maxSpeed)} <small style="display:inline">m/s</small></strong></div>`;const b=document.createElement('button');b.className='launch-button';b.textContent='Back to the workshop';b.onclick=returnToBuild;r.append(symbol,h,p,stats,b);$('#flight-slot').append(r);b.focus({preventScroll:true});$('#control-slot').replaceChildren();}
async function launch(){if(mode==='result'){returnToBuild();return;}if(mode!=='build'||!scene)return;closePicker();mode='countdown';const id=++runId;launchCount++;render();$('#viewport-status').textContent='LAUNCH SEQUENCE';$('.viewport-number').hidden=true;$('.viewport-caption').hidden=true;$('#viewport').scrollIntoView({block:'center',behavior:'smooth'});
 for(let n=3;n>0;n--){if(runId!==id)return;$('#flight-slot').innerHTML=`<div class="countdown" role="status">${n}</div>`;await new Promise(r=>setTimeout(r,850));}
 mode='flight';flight=createFlight(build,WEATHER[weatherIndex]);throttle=1;$('#flight-slot').innerHTML='<div class="flight-hud"><div class="flight-phase" id="flight-phase"></div><div class="telemetry"><div><small>ALTITUDE</small><strong id="altitude">0</strong> <em>km</em></div><div><small>VELOCITY</small><strong id="velocity">0</strong> <em>m/s</em></div><div><small>FUEL</small><strong id="flight-fuel">100</strong> <em>%</em></div></div><p class="flight-message" id="flight-message"></p></div>';$('#control-slot').innerHTML='<div class="flight-controls"><div class="label-row"><label for="throttle">Engine throttle</label><span id="throttle-label">100%</span></div><input id="throttle" type="range" min="40" max="100" value="100" step="5"><button class="secondary-button abort-button" id="abort">Cut engines & return</button></div>';$('#throttle').oninput=e=>{throttle=Number(e.target.value)/100;$('#throttle-label').textContent=e.target.value+'%';};$('#abort').onclick=()=>{flight.aborted=true;$('#abort').disabled=true;$('#abort').textContent='Engines cut';$('#throttle').disabled=true;};$('#viewport-status').textContent='LIVE TELEMETRY';$('#model-tag').textContent='FLIGHT '+String(launchCount).padStart(3,'0');render();let last=performance.now();
 function tick(now){if(id!==runId||mode!=='flight')return;const elapsed=Math.min((now-last)/1000,.1);last=now;const speed=flight.chute?140:flight.phase==='descent'||flight.phase==='coast'?40:10;let remaining=elapsed*speed;while(remaining>0&&flight.status==='flying'){const step=Math.min(remaining,.05);stepFlight(flight,step,throttle);remaining-=step;}scene.setFlight(flight);renderFlight();if(flight.status!=='flying'){setTimeout(()=>{if(id===runId)finishFlight();},flight.status==='destroyed'?1600:500);return;}requestAnimationFrame(tick);}
 requestAnimationFrame(tick);
}
$('#launch').onclick=launch;render();
// Feature-detected structured controls use exactly the same actions as the UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'inspect_rocket',description:'Read the current rocket configuration, weather, and preflight warnings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({build:{...build},weather:WEATHER[weatherIndex],mode,warnings:statsFor(build,WEATHER[weatherIndex]).issues})});
 register({name:'configure_rocket_part',description:'Change one rocket part in the workshop. Does not launch.',inputSchema:{type:'object',properties:{category:{type:'string',enum:Object.keys(PARTS)},partId:{type:'string'}},required:['category','partId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['category','partId'].includes(k)))throw Error('Invalid part configuration.');choosePart(input.category,input.partId);return {build:{...build},warnings:statsFor(build,WEATHER[weatherIndex]).issues};}});
 addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
